static FILE* trace_file;
static int trace_tick=-180,trace_sequence;
static void state_trace(const char* event,const belt_body* b,double theta,double nx,double ny,double depth){
 if(!trace_file)return;
 belt_residual r[BELT_MAX_RESIDUALS];double md,total=0,bend=0,maxbend=0;int row=-1,n=belt_residuals(b,b->q,r,&md);
 for(int i=0;i<n;++i){double e=.5*r[i].k*r[i].value*r[i].value;total+=e;if(i<2*BELT_Q&&(i&1)){bend+=e;if(e>maxbend){maxbend=e;row=i;}}}
 double bounds[4],foot;belt_bounds(b->q,bounds,&foot);
 fprintf(trace_file,"%d,%d,%.0f,%s,%.17g,%.17g,%.17g,%d,%.17g,%.17g,%.17g,%.17g,%.17g,%.17g,%.17g,%.0f,%.0f,%.17g",
 trace_sequence++,trace_tick,b->solver_diag[4],event,total,bend,maxbend,row,md,theta,nx,ny,depth,b->q[34],b->q[35],b->solver_diag[3],b->solver_diag[5],b->solver_diag[7]);
 for(int j=0;j<BELT_D;++j)fprintf(trace_file,",%.17g",b->q[j]);
 for(int j=0;j<BELT_D;++j)fprintf(trace_file,",%.17g",b->v[j]);
 fputc('\n',trace_file);
 if((maxbend>1000&&event[0]=='s')||(trace_tick>=608&&event[0]=='b')){
   char path[200];sprintf_s(path,sizeof path,"state-%06d-%s.bin",trace_sequence-1,event);FILE* f=NULL;fopen_s(&f,path,"wb");
   if(f){fwrite(room_active,sizeof *room_active,1,f);fwrite(b,sizeof *b,1,f);fclose(f);}
 }
}

