static int addboth(void*h,void*n,dango_belt_room_definition d){dango_belt_room_collection_frame f;dango_belt_room_collection_probe p;dango_belt_room_collection_token t;nread(n,&f,sizeof f);int rc=nprepare(n,1,0,f.base.scene_revision,&d,&p,sizeof p,&t);if(rc||p.rejection){printf("native add fail %d %d %.17g\n",rc,p.rejection,p.minimum_gap);return 1;}if(napply(n,&t))return 1;return add(h,d);}
